import React from 'react';
import { Play, Pause, RotateCcw, Activity, Shield, AlertTriangle, CheckCircle } from 'lucide-react';
const Dashboard = ({ isRunning, onStart, onStop, onReset, metrics }) => {
  const getHealthColor = (health) => {
    if (health >= 80) return '#10b981';
    if (health >= 50) return '#f59e0b';
    return '#ef4444';
  };

  const getHealthStatus = (health) => {
    if (health >= 80) return 'Optimal';
    if (health >= 50) return 'Degraded';
    return 'Critical';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-gray-100 p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-10">
          <h1 className="text-4xl font-bold text-gray-900 mb-2 tracking-tight">Network Security Monitor</h1>
          <p className="text-gray-600 text-lg">Real-time threat detection and system analytics</p>
        </div>

        {/* Control Panel */}
        <div className="bg-white rounded-3xl shadow-lg border border-gray-200 p-8 mb-8">
          <div className="flex flex-wrap items-center gap-4">
            <button
              className={`flex items-center gap-3 px-8 py-4 rounded-2xl font-semibold transition-all duration-300 ${
                isRunning 
                  ? 'bg-gradient-to-r from-red-500 to-red-600 hover:from-red-600 hover:to-red-700 text-white shadow-lg shadow-red-500/30' 
                  : 'bg-gradient-to-r from-emerald-500 to-teal-500 hover:from-emerald-600 hover:to-teal-600 text-white shadow-lg shadow-emerald-500/30'
              }`}
              onClick={isRunning ? onStop : onStart}
            >
              {isRunning ? (
                <>
                  <Pause size={22} />
                  <span>Stop Simulation</span>
                </>
              ) : (
                <>
                  <Play size={22} />
                  <span>Start Simulation</span>
                </>
              )}
            </button>

            <button 
              className="flex items-center gap-3 px-8 py-4 rounded-2xl font-semibold bg-white hover:bg-gray-50 text-gray-700 border-2 border-gray-300 transition-all duration-300 shadow-md"
              onClick={onReset}
            >
              <RotateCcw size={22} />
              <span>Reset System</span>
            </button>

            <div className={`ml-auto flex items-center gap-3 px-6 py-4 rounded-2xl font-semibold border-2 transition-all duration-300 ${
              isRunning 
                ? 'bg-emerald-50 text-emerald-700 border-emerald-300' 
                : 'bg-gray-100 text-gray-600 border-gray-300'
            }`}>
              <Activity size={22} className={isRunning ? 'animate-pulse' : ''} />
              <span className="font-mono font-bold">{isRunning ? 'RUNNING' : 'STOPPED'}</span>
            </div>
          </div>
        </div>

        {/* Metrics Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {/* Total Packets Card */}
          <div className="bg-white rounded-3xl shadow-lg border border-gray-200 p-8 hover:shadow-xl transition-all duration-300 group">
            <div className="flex items-center justify-between mb-6">
              <div className="p-4 bg-gradient-to-br from-blue-500 to-blue-600 rounded-2xl shadow-lg shadow-blue-500/30 group-hover:scale-110 transition-transform duration-300">
                <Activity size={32} className="text-white" />
              </div>
            </div>
            <h3 className="text-gray-500 text-sm font-semibold uppercase tracking-wider mb-3">Total Packets</h3>
            <p className="text-5xl font-bold text-gray-900 mb-4">{metrics.totalPackets.toLocaleString()}</p>
            <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-blue-500 to-blue-600 rounded-full transition-all duration-500" style={{ width: '100%' }}></div>
            </div>
          </div>

          {/* Blocked Packets Card */}
          <div className="bg-white rounded-3xl shadow-lg border border-gray-200 p-8 hover:shadow-xl transition-all duration-300 group">
            <div className="flex items-center justify-between mb-6">
              <div className="p-4 bg-gradient-to-br from-red-500 to-red-600 rounded-2xl shadow-lg shadow-red-500/30 group-hover:scale-110 transition-transform duration-300">
                <Shield size={32} className="text-white" />
              </div>
            </div>
            <h3 className="text-gray-500 text-sm font-semibold uppercase tracking-wider mb-3">Blocked Packets</h3>
            <p className="text-5xl font-bold text-gray-900 mb-4">{metrics.blockedPackets.toLocaleString()}</p>
            <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-red-500 to-red-600 rounded-full transition-all duration-500" 
                   style={{ width: `${Math.min((metrics.blockedPackets / metrics.totalPackets) * 100, 100)}%` }}></div>
            </div>
          </div>

          {/* Attacks Detected Card */}
          <div className="bg-white rounded-3xl shadow-lg border border-gray-200 p-8 hover:shadow-xl transition-all duration-300 group">
            <div className="flex items-center justify-between mb-6">
              <div className="p-4 bg-gradient-to-br from-amber-500 to-orange-500 rounded-2xl shadow-lg shadow-amber-500/30 group-hover:scale-110 transition-transform duration-300">
                <AlertTriangle size={32} className="text-white" />
              </div>
            </div>
            <h3 className="text-gray-500 text-sm font-semibold uppercase tracking-wider mb-3">Attacks Detected</h3>
            <p className="text-5xl font-bold text-gray-900 mb-4">{metrics.attacksDetected.toLocaleString()}</p>
            <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
              <div className="h-full bg-gradient-to-r from-amber-500 to-orange-500 rounded-full transition-all duration-500" style={{ width: '75%' }}></div>
            </div>
          </div>

          {/* System Health Card */}
          <div className="bg-white rounded-3xl shadow-lg border border-gray-200 p-8 hover:shadow-xl transition-all duration-300 group">
            <div className="flex items-center justify-between mb-6">
              <div className={`p-4 rounded-2xl shadow-lg group-hover:scale-110 transition-transform duration-300 ${
                metrics.systemHealth >= 80 
                  ? 'bg-gradient-to-br from-emerald-500 to-teal-500 shadow-emerald-500/30' 
                  : metrics.systemHealth >= 50 
                  ? 'bg-gradient-to-br from-amber-500 to-orange-500 shadow-amber-500/30' 
                  : 'bg-gradient-to-br from-red-500 to-red-600 shadow-red-500/30'
              }`}>
                <CheckCircle size={32} className="text-white" />
              </div>
            </div>
            <h3 className="text-gray-500 text-sm font-semibold uppercase tracking-wider mb-3">System Health</h3>
            <p className="text-5xl font-bold mb-4" style={{ color: getHealthColor(metrics.systemHealth) }}>
              {metrics.systemHealth}%
            </p>
            <span className={`inline-block px-4 py-2 rounded-xl text-sm font-bold ${
              metrics.systemHealth >= 80 
                ? 'bg-emerald-100 text-emerald-700' 
                : metrics.systemHealth >= 50 
                ? 'bg-amber-100 text-amber-700' 
                : 'bg-red-100 text-red-700'
            }`}>
              {getHealthStatus(metrics.systemHealth)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
